#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=6

# Everything below this line is authored for this procedure.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WORKER_DIR="$REPO_ROOT/serverless"
ARTIFACT="$REPO_ROOT/docs/artifacts/s311-rotation-hardware.txt"
SECRET_NAME="GOOGLE_API_KEY"
MOLE_FILE='C:\ProgramData\LockdownAgent\.runtime_settings'

# This host keeps Node outside the default PATH (AGENTS.md).
[[ -d "$HOME/.local/node/bin" ]] && export PATH="$HOME/.local/node/bin:$PATH"

EVIDENCE=()
FAILURES=0
_record() { EVIDENCE+=("$1"); }
_pass() { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; _record "PASS  $1"; }
_fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; _record "FAIL  $1"; FAILURES=$((FAILURES + 1)); }

# _field JSON KEY — print one field of the pasted override, or nothing.
_field() {
  python3 -c 'import json,sys
try:
    d = json.loads(sys.argv[1])
except Exception:
    print(""); raise SystemExit(0)
v = d.get(sys.argv[2]) if isinstance(d, dict) else None
print("" if v is None else v)' "$1" "$2"
}

# _put_secret VALUE — set the Worker secret from stdin (non-interactive).
_put_secret() {
  printf '%s' "$1" | ( cd "$WORKER_DIR" && npx wrangler secret put "$SECRET_NAME" 2>&1 )
}

_mole_prompt() {
  say "On MOLE, in an elevated PowerShell, run:"
  step "Get-Content '${MOLE_FILE}' -Raw"
  note "MOLE checks in every poll interval (30 s, longer when the device is idle)."
  note "Give it up to ~5 minutes before assuming something is wrong."
  warn "The text you paste contains the key. It is never written to disk unredacted."
}

banner "Rotate the geolocation key on real hardware"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "The key you intend to keep"
for tool in npx python3; do
  command -v "$tool" >/dev/null 2>&1 || warn "${tool} is not on PATH — this wizard needs it"
done
say "This sets GOOGLE_API_KEY on the deployed Worker, so every enrolled device that"
say "checks in receives it. On this lab that is MOLE alone — confirm that is true,"
say "because the key becomes a shared credential for whatever is enrolled."
note "A real Google Geolocation API key is the point of this run: it is what an"
note "interactive install would use to triangulate. It is entered hidden."
open_url "https://console.cloud.google.com/apis/credentials"
ask_secret KEY_KEEP "Paste the real geolocation key:"
if [[ -z "${KEY_KEEP:-}" ]]; then
  warn "no key entered — nothing to rotate. Re-run when you have one."
  exit 1
fi
if [[ ${#KEY_KEEP} -lt 20 ]]; then
  warn "that is shorter than any real Google API key; continuing anyway, but say so in the artifact"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Set the Worker secret"
say "Secrets take effect on the next request — no deploy, no redeploy of the code."
_out=$(_put_secret "$KEY_KEEP" || true)
printf '%s\n' "$_out" | sed 's/^/    /'
if printf '%s' "$_out" | grep -qiE "success|uploaded|created the secret"; then
  _pass "Worker secret ${SECRET_NAME} set (${#KEY_KEEP} chars)"
else
  _fail "Worker secret not confirmed — read the output above before continuing"
  if ! confirm "Continue anyway?"; then exit 1; fi
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "MOLE picks it up (no restart)"
_mole_prompt
ask MOLE_JSON_1 "Paste the override JSON from MOLE:"
KEY1_SEEN=$(_field "$MOLE_JSON_1" google_api_key)
REV1=$(_field "$MOLE_JSON_1" revision)
if [[ "$KEY1_SEEN" == "$KEY_KEEP" ]]; then
  _pass "MOLE wrote the key from stage 1 to .runtime_settings"
else
  _fail "MOLE's google_api_key is not the key from stage 1 (file may not exist yet, or still the install-time key)"
fi
if [[ "$REV1" =~ ^[0-9a-f]{16}$ ]]; then
  _pass "revision is a 16-char digest (${REV1})"
else
  _fail "revision missing or not a 16-char hex digest: '${REV1}'"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Rotate — the decisive step"
KEY_TEMP="ROT-TEST-$(date +%s)"
say "Setting a throwaway value now. It will never reach Google, so no location will"
say "resolve for one poll interval; that is expected and is the whole point: if the"
say "file changes, the agent rotated WITHOUT being restarted."
note "throwaway value: ${KEY_TEMP}"
if ! confirm "Set the throwaway value on the live Worker now?"; then
  warn "stopped before touching the Worker — the real key from stage 1 is still in place"
  exit 1
fi
_out=$(_put_secret "$KEY_TEMP" || true)
printf '%s\n' "$_out" | sed 's/^/    /'
_mole_prompt
ask MOLE_JSON_2 "Paste the override JSON from MOLE:"
KEY2_SEEN=$(_field "$MOLE_JSON_2" google_api_key)
REV2=$(_field "$MOLE_JSON_2" revision)
if [[ "$KEY2_SEEN" == "$KEY_TEMP" ]]; then
  _pass "MOLE rotated to the throwaway value with no agent restart"
else
  _fail "MOLE still shows a different key — the rotation did not land"
fi
if [[ -n "$REV2" && "$REV2" != "$REV1" ]]; then
  _pass "revision changed (${REV1} -> ${REV2})"
else
  _fail "revision did not change (still '${REV2}')"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Put the real key back"
say "Restoring the key from stage 1. Everything enrolled goes back to being able to"
say "triangulate, and the override should change a third time."
_out=$(_put_secret "$KEY_KEEP" || true)
printf '%s\n' "$_out" | sed 's/^/    /'
_mole_prompt
ask MOLE_JSON_3 "Paste the override JSON from MOLE:"
KEY3_SEEN=$(_field "$MOLE_JSON_3" google_api_key)
REV3=$(_field "$MOLE_JSON_3" revision)
if [[ "$KEY3_SEEN" == "$KEY_KEEP" ]]; then
  _pass "MOLE is back on the real key (${#KEY_KEEP} chars)"
else
  _fail "MOLE is not back on the real key"
fi
if [[ -n "$REV3" && "$REV3" != "$REV2" ]]; then
  _pass "revision changed again (${REV2} -> ${REV3})"
else
  _fail "revision did not change after the restore (still '${REV3}')"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Record the evidence"
{
  printf '=== S311: ADR-010 rotation exercised on real hardware (MOLE) ===\n'
  printf 'date: %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf 'worker: lockdown-serverless · secret %s was set, rotated, restored\n' "$SECRET_NAME"
  printf 'override file on MOLE: %s\n' "$MOLE_FILE"
  printf 'key material is redacted: lengths and revisions only, never the value\n\n'
  printf -- '--- assertions ---\n'
  printf '%s\n' "${EVIDENCE[@]}"
  printf '\n--- revisions observed ---\n'
  printf 'after set     : %s\n' "${REV1:-<none>}"
  printf 'after rotate  : %s\n' "${REV2:-<none>}"
  printf 'after restore : %s\n' "${REV3:-<none>}"
  printf '\nkey length kept: %s chars · throwaway length: %s chars\n' "${#KEY_KEEP}" "${#KEY_TEMP}"
  printf '\nfailures: %s\n' "$FAILURES"
} > "$ARTIFACT"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$ARTIFACT"
note "the key itself was never written to that file — check with: grep -c ROT-TEST '$ARTIFACT'"

if (( FAILURES == 0 )); then
  printf '\n  %sAll %s assertions passed.%s\n' "$GREEN" "${#EVIDENCE[@]}" "$RESET"
else
  printf '\n  %s%s assertion(s) failed — see %s%s\n' "$RED" "$FAILURES" "$ARTIFACT" "$RESET"
fi

finish
